import { demoOpportunityCards } from './opportunity-radar.js';
import { representativeAssets, proofLevel } from './thematic-radar-data.js';
import { openDetails } from './asset-details.js';

function esc(value){const n=document.createElement('div');n.textContent=value;return n.innerHTML;}
function list(title,values){return `<div class="opportunity-detail"><strong>${esc(title)}</strong><ul>${(values?.length?values:['Aucun élément renseigné']).map(v=>`<li>${esc(v)}</li>`).join('')}</ul></div>`;}
function loadCss(){if(document.querySelector('link[data-thematic-radar]'))return;const l=document.createElement('link');l.rel='stylesheet';l.href='thematic-radar.css';l.dataset.thematicRadar='true';document.head.append(l);}
function dialog(){let d=document.getElementById('thematicRadarDialog');if(d)return d;d=document.createElement('dialog');d.id='thematicRadarDialog';d.className='thematic-radar-dialog';d.innerHTML='<div data-thematic-content></div>';document.body.append(d);d.addEventListener('click',e=>{if(e.target===d)d.close();});return d;}
function assetCard(asset,index){return `<article class="theme-asset-card"><div><span class="badge">${esc(asset.type)}</span><h4>${esc(asset.name)}</h4><small>${esc(asset.ticker)}</small></div><p>${esc(asset.role)}</p><div class="theme-asset-meta"><span>Exposition : ${esc(asset.exposure)}</span><span>Risque : ${esc(asset.risk)}</span></div><button type="button" class="btn secondary" data-theme-asset="${index}">Voir la fiche réelle</button></article>`;}
function scoreStatus(){return '<strong>Non calculé</strong><span>score LEYNOR du thème</span><small>Aucune méthodologie validée ne permet encore d’afficher un score.</small>';}

function openTheme(card){
  const d=dialog();const c=d.querySelector('[data-thematic-content]');const assets=representativeAssets(card.id);
  c.innerHTML=`<header class="thematic-head"><div><p>FICHE THÉMATIQUE</p><h2>${esc(card.asset)}</h2><span>${esc(card.category)} · ${esc(card.horizon)}</span></div><button type="button" data-close-theme aria-label="Fermer">×</button></header><section class="thematic-score"><div class="thematic-score-unavailable">${scoreStatus()}</div><div><strong>${Math.round(card.confidence*100)} %</strong><span>niveau de confiance</span></div><div><strong>${proofLevel(card)}</strong><span>niveau de preuve provisoire</span></div></section><p class="thematic-warning">Le score, la confiance et le niveau de preuve sont trois informations distinctes. Aucun score thématique n’est copié sur les entreprises ou ETF présentés.</p><section><h3>Pourquoi LEYNOR surveille ce thème</h3><p>${esc(card.thesis)}</p></section><div class="thematic-evidence">${list('Facteurs favorables',card.favorableEvidence)}${list('Éléments contradictoires',card.counterEvidence)}${list('Risques',card.risks)}</div><section class="thematic-assets"><div class="thematic-section-head"><p>ACTIFS REPRÉSENTATIFS</p><h3>Entreprises et ETF à examiner séparément</h3></div>${assets.length?`<div class="theme-assets-grid">${assets.map(assetCard).join('')}</div>`:'<p>Aucun instrument coté fiable n’est encore associé à ce thème.</p>'}</section><details class="thematic-method"><summary>Sources, méthode et limites</summary>${list('Sources déclarées',card.sources)}${list('Limites',card.limitations)}<small>Fraîcheur des données : ${esc(card.freshness)}</small></details>`;
  c.querySelector('[data-close-theme]')?.addEventListener('click',()=>d.close());
  c.querySelectorAll('[data-theme-asset]').forEach(b=>b.addEventListener('click',()=>{const asset=assets[Number(b.dataset.themeAsset)];if(!asset)return;d.close();openDetails({...asset,price:null,change:null});}));
  if(!d.open)d.showModal();
}

function createOpportunitySection(){
  loadCss();if(document.querySelector('[data-opportunity-radar]'))return;const radar=document.querySelector('#radar');if(!radar)return;const cards=demoOpportunityCards.slice(0,3);const section=document.createElement('article');section.className='panel opportunity-radar';section.dataset.opportunityRadar='true';section.innerHTML=`<div class="panel-head"><div><p class="eyebrow">RADAR EXPLICABLE</p><h2>Opportunités à étudier</h2></div><a class="btn secondary" href="trends.html">Voir les preuves</a></div><p class="subtitle">Aucun score LEYNOR n’est affiché tant qu’il n’est pas validé. La confiance et le niveau de preuve restent présentés séparément.</p><div class="opportunity-grid">${cards.map((card,index)=>`<article class="opportunity-card"><div class="opportunity-top"><div><span class="badge">${esc(card.category)}</span><h3>${esc(card.asset)}</h3></div><div class="opportunity-confidence"><strong>${Math.round(card.confidence*100)} %</strong><small>confiance</small></div></div><p>${esc(card.thesis)}</p><div class="opportunity-meta"><span>Score : non calculé</span><span>Preuve : ${proofLevel(card)}</span><span>${esc(card.horizon)}</span></div><button type="button" class="btn secondary opportunity-open-theme" data-open-theme="${index}">Pourquoi LEYNOR pense cela ?</button></article>`).join('')}</div>`;radar.insertAdjacentElement('afterend',section);section.querySelectorAll('[data-open-theme]').forEach(b=>b.addEventListener('click',()=>openTheme(cards[Number(b.dataset.openTheme)])));
}

if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',createOpportunitySection);else createOpportunitySection();
export{createOpportunitySection,openTheme};
